fn actor_receiving_result(receipt:semio_framework_actor::RetainedTurnReceipt,more_work:bool)->semio_framework_actor::TurnResult{semio_framework_actor::TurnResult{retained_receipt:receipt,ui_patches:Vec::new(),effects:Vec::new(),command_ingress:Vec::new(),cold_pair_ingress:Default::default(),lifecycle_receipt:None,ui_patch_receipt:None,next_wake:None,status:if more_work{semio_framework_actor::TurnStatus::MoreWork}else{semio_framework_actor::TurnStatus::Idle},usage:semio_framework_actor::Usage{fuel:0,wall_us:0,memory_bytes:0}}}
async fn original_scheduler_input(kernel:&mut semio_framework_actor::Kernel,actor:semio_framework_actor::ActorId,sequence:u64)->semio_framework_actor::RetainedTurnInput{let envelope=semio_framework_actor::Envelope{to:actor,from:semio_framework_actor::Origin::Kernel,lane:semio_framework_actor::Lane::Interactive,seq:sequence,deadline_ms:None,coalesce:None,cancel_of:None,payload:semio_framework_actor::Payload::Event{bytes:Vec::new()}};assert_ne!(kernel.submit(&envelope).await,semio_framework_actor::Backpressure::Rejected);*kernel.tick(sequence).await.run.pop().unwrap().original_input()}

#[semio_framework_async_macros::async_test]
async fn original_host_factory_admission_receives_real_guest_once_and_keeps_scheduler_input(){
 use semio_framework_actor::{retained_turn::{OriginalActorInput,ActorGuestPhase},RetainedTurnInput};
 use semio_framework_plugin_host_guest_runtime::{MockGuestRuntime,GuestInstanceState,MockInstanceState};
 use semio_framework_actor::ActorId as RuntimeActorId;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️context/🤝️admission/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 let grant=|row:&serde_json::Value|RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize};
 let initial=RetainedTurnInput{operation:71,generation:3,epoch:19,work: semio_framework_actor::OriginalActorTurnWork{clock_binding:1,absolute_deadline_us:u64::MAX,fuel:1_000_000}, grant:grant(&fixture["originalGrant"])};
 let mut kernel=semio_framework_actor::Kernel::new(semio_framework_actor::ShardKind::Native,2,0,1).await;let package=semio_framework_actor::PackageId("original-host-receiving".into());let actor=kernel.activate(package.clone(),7,semio_framework_actor::ActorKind::PluginApp{plugin:package,app_id:"original".into(),instance_id:0},semio_framework_actor::Lane::Interactive,None,semio_framework_actor::ActivationEvent::Manual,initial,semio_framework_actor::OriginalActorTurnLoan{retained_policy:initial.grant,work_fuel:initial.work.fuel,deadline_us:initial.work.absolute_deadline_us}).await;
 let mut sequence=1;let mut input=original_scheduler_input(&mut kernel,actor,sequence).await;assert_eq!(input,initial);
 let mut source=Vec::with_capacity(fixture["sourceCapacity"].as_u64().unwrap()as usize);source.extend_from_slice(&[81u8;7]);let pointer=source.as_ptr();let mut original=OriginalActorInput::new(source,input).ok().unwrap();
 let policy:ShardIdentityPolicy=serde_json::from_str(include_str!("../⚙️configuration/🔣️.json")).unwrap();let mut identity=OriginalShardIdentity::issue(policy,Box::new(|_|true),Box::new(|_|Ok(()))).unwrap();let identity_recipient=std::ptr::from_ref(identity.recipient.as_ref().get_ref());let identity_bytes=identity.owned_bytes();let runtime=GuestRuntimes::Mock(Arc::new(MockGuestRuntime::default()));let mut instance=GuestInstance{actor:RuntimeActorId(71),state:GuestInstanceState::Mock(MockInstanceState::default())};let guest_policy=grant(&fixture["fixedGuestPolicy"]);
 for index in 0..4{
  let(returned,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(identity.admit_actor_original(&runtime,&mut instance,&mut original,semio_framework::kernel::Budget::from_retained(input,100,1,0,0),guest_policy)));
  let returned=returned.unwrap().unwrap();let reply=returned.call.unwrap();assert!(reply.refusal.is_none());let receipt=returned.receiving.unwrap();assert_eq!(receipt.input,input);assert_eq!(heap.requested_bytes,reply.spent.retained_capacity_bytes);assert_eq!(heap.released_bytes,reply.spent.released_bytes);let expected=&fixture["spent"][index];assert_eq!([reply.spent.copied_items,reply.spent.copied_bytes,reply.spent.retained_capacity_bytes,reply.spent.released_bytes],std::array::from_fn(|axis|expected[axis].as_u64().unwrap()as usize));assert_eq!(original.original().unwrap().as_ptr(),pointer);assert!(original.return_actor_turn().is_err());assert_eq!(std::ptr::from_ref(identity.recipient.as_ref().get_ref()),identity_recipient);assert_eq!(identity.owned_bytes(),identity_bytes);kernel.complete(actor,&actor_receiving_result(receipt,true),sequence).await.unwrap();sequence+=1;input=original_scheduler_input(&mut kernel,actor,sequence).await;original.receive_next_issued(input).unwrap();
 }
 let GuestInstanceState::Mock(state)=&mut instance.state else{unreachable!()};let checked=original.checkout_guest(RetainedCloneGrant{maximum_copy_bytes:7,..guest_policy}).unwrap().unwrap();let mut recipient=Default::default();let(call,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||state.actor_context.dispatch_step(checked,semio_framework_job::StepBudget::new(100,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us,|cx|{let mut target=[0;7];target.copy_from_slice(original.original().unwrap());assert_eq!(target,[81;7]);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()}).unwrap();Ok(())}));assert!(call.result.is_ok());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));original.receive_guest_spent(call.input,call.receipt_spent,call.work_units_spent,ActorGuestPhase::Dispatched).unwrap();let receipt=original.return_actor_turn().unwrap();kernel.complete(actor,&actor_receiving_result(receipt,true),sequence).await.unwrap();sequence+=1;input=original_scheduler_input(&mut kernel,actor,sequence).await;original.receive_next_issued(input).unwrap();
 let source=original.take_dispatched_input().unwrap().unwrap();assert_eq!(source.as_ptr(),pointer);let checked=original.checkout_guest(guest_policy).unwrap().unwrap();assert!(checked.grant.maximum_release_bytes>=source.capacity());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(source));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,97));original.receive_guest_spent(checked,RetainedCloneProgress{copied_items:1,released_bytes:97,..Default::default()},1,ActorGuestPhase::Dispatched).unwrap();let receipt=original.return_actor_turn().unwrap();kernel.complete(actor,&actor_receiving_result(receipt,true),sequence).await.unwrap();
 let mut released=0;while !state.actor_context.terminal_is_empty(){sequence+=1;input=original_scheduler_input(&mut kernel,actor,sequence).await;original.receive_next_issued(input).unwrap();let checked=original.checkout_guest(guest_policy).unwrap().unwrap();let(call,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||state.actor_context.close_step(checked,guest_policy));assert!(call.result.is_ok());assert_eq!((heap.requested_bytes,heap.released_bytes),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));released+=heap.released_bytes;let more_work=!state.actor_context.terminal_is_empty();original.receive_guest_spent(call.input,call.receipt_spent,call.work_units_spent,ActorGuestPhase::Dispatched).unwrap();let receipt=original.return_actor_turn().unwrap();kernel.complete(actor,&actor_receiving_result(receipt,more_work),sequence).await.unwrap();assert!(sequence<32)}assert_eq!(released,192);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{drop(instance);drop(original)});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
}

#[test]
fn shard_original_identity_loans_preserve_partial_children_and_actor_ledgers(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../⚡️effects/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 let policy:ShardIdentityPolicy=serde_json::from_value(fixture["identityPolicy"].clone()).unwrap();
 let source="文🌠".repeat(20000);let allow=Arc::new(AtomicBool::new(false));let original_allow=Arc::clone(&allow);
 let calls=Arc::new(AtomicUsize::new(0));let original_calls=Arc::clone(&calls);
 let ledger=Arc::new(AtomicUsize::new(0));let original_ledger=Arc::clone(&ledger);
 let mut first=OriginalShardIdentity::issue(policy,Box::new(move |event:NativeEncodeProgress|{original_calls.fetch_add(1,Ordering::Relaxed);original_allow.load(Ordering::Relaxed)||event.total!=140000||event.completed<65535}),Box::new(move |request:NativeEncodeAllocation|{assert_eq!(request.owned_bytes,original_ledger.load(Ordering::Relaxed));assert_eq!(request.next_owned_bytes,request.owned_bytes+request.bytes);original_ledger.store(request.next_owned_bytes,Ordering::Relaxed);Ok(())})).unwrap();
 let mut second=OriginalShardIdentity::issue(policy,Box::new(|_|true),Box::new(|_|Ok(()))).unwrap();
 let second_before=second.owned_bytes();let original_recipient=std::ptr::from_ref(first.recipient.as_ref().get_ref());
 let mut identity=first.loan().unwrap();
 let (result,birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||identity.encode(|native|native.with_retirement_owner(std::mem::size_of::<ControlledRetirement<Vec<u8>>>(),|native|{let mut original=ControlledRetirement::new(Vec::<u8>::new()).ok().unwrap();let result=native.append_bytes(original.original_mut().unwrap(),source.as_bytes());assert_eq!(original.original_mut().unwrap().as_slice(),&source.as_bytes()[..65535]);(result,Some(Box::new(original)as Box<dyn ErasedSnapshotRetirement>))})));
 assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert!(birth.requested_bytes>0);assert_eq!(birth.released_bytes,0);
 drop(identity);let retained=first.owned_bytes();assert_eq!(retained,ledger.load(Ordering::Relaxed));assert_eq!(second.owned_bytes(),second_before);assert!(first.recipient.has_owner());
 let mut other=second.loan().unwrap();other.encode::<_,ValueError>(|native|native.charge(7)).unwrap();drop(other);assert_eq!(second.owned_bytes(),second_before+7);assert_eq!(first.owned_bytes(),retained);
 {let mut suspended=std::pin::pin!(async{let mut original=first.loan().unwrap();original.encode::<_,ValueError>(|native|native.charge(1)).unwrap();std::future::pending::<()>().await;drop(original);});let mut context=std::task::Context::from_waker(std::task::Waker::noop());assert!(std::future::Future::poll(suspended.as_mut(),&mut context).is_pending());}
 assert_eq!(first.owned_bytes(),retained+1);assert_eq!(first.owned_bytes(),ledger.load(Ordering::Relaxed));assert!(first.recipient.has_owner());assert_eq!(std::ptr::from_ref(first.recipient.as_ref().get_ref()),original_recipient);
 allow.store(true,Ordering::Relaxed);let mut released=0;let mut copied=0;let mut closing_birth=0;let mut turns=0;
 while first.recipient.has_owner(){
  let mut identity=first.loan().unwrap();let (step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||identity.encode(|native|native.close_retirement_recipient(policy.grant)));let step=step.unwrap();let progress=match step{RetainedCloneStep::Progress(progress)|RetainedCloneStep::Complete(progress)=>progress};assert!(progress.fits(policy.grant));assert_eq!(heap.released_bytes,progress.released_bytes);assert!(heap.requested_bytes<=progress.retained_capacity_bytes);released+=progress.released_bytes;closing_birth+=heap.requested_bytes;copied+=progress.copied_items;drop(identity);turns+=1;assert!(turns<100000);
 }
 assert_eq!(released,birth.requested_bytes+closing_birth);assert_eq!(std::ptr::from_ref(first.recipient.as_ref().get_ref()),original_recipient);assert_eq!(first.owned_bytes(),ledger.load(Ordering::Relaxed));assert!(copied>0);assert!(calls.load(Ordering::Relaxed)>1);assert_eq!(serde_json::to_value(&source[..65535]).unwrap(),serde_json::Value::String(String::from_utf8(source.as_bytes()[..65535].to_vec()).unwrap()));
}

#[test]
fn shard_original_identity_slot_requires_each_original_positive_axis(){
 let policy:ShardIdentityPolicy=serde_json::from_str(include_str!("../⚙️configuration/🔣️.json")).unwrap();let bytes=std::mem::size_of::<NativeEncodeRetirementRecipient>();
 for axis in ["items","copy","capacity","depth"]{let mut denied=policy;match axis{"items"=>denied.grant.maximum_items=0,"copy"=>denied.grant.maximum_copy_bytes=bytes-1,"capacity"=>denied.grant.maximum_capacity_bytes=bytes-1,_=>denied.grant.maximum_depth=0};let count=Arc::new(AtomicUsize::new(0));let original=Arc::clone(&count);let observer=Box::new(|_|true);let allocation=Box::new(move |_|{original.fetch_add(1,Ordering::Relaxed);Ok(())});let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||OriginalShardIdentity::issue(denied,observer,allocation));assert!(matches!(result,Err(ref error)if error.error.kind==ValueRefusalKind::OwnershipLimit));assert_eq!(count.load(Ordering::Relaxed),0);assert_eq!(heap.requested_bytes,0);}
 let mut recipient=NativeEncodeRetirementRecipient::new();let original_address=std::ptr::from_ref(&recipient);let mut observer=|_|true;let mut allocate=|_:NativeEncodeAllocation|Ok(());let admitted=serde_json::from_str::<String>("\"文🌠\"").unwrap().len();let mut native=NativeEncodeControl::new_forwarded(policy.maximum_bytes,&mut observer,&mut allocate);native.install_retirement_recipient(&mut recipient).unwrap();native.charge(admitted).unwrap();let receipt=native.detach().ok().unwrap();let mut original=std::mem::replace(&mut recipient,NativeEncodeRetirementRecipient::new());assert_eq!(std::ptr::from_ref(&recipient),original_address);let(error,receipt)=match receipt.bind(&mut allocate,&mut recipient){Err(refused)=>refused,Ok(_)=>panic!("a new recipient at the original address must refuse the consuming receipt")};assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!(receipt.owned_bytes(),admitted);let continuation=receipt.bind(&mut allocate,&mut original).ok().unwrap();let receipt=continuation.detach().unwrap();assert_eq!(receipt.owned_bytes(),admitted);assert_eq!(receipt.maximum_bytes(),policy.maximum_bytes);
}

#[semio_framework_async_macros::async_test]
async fn original_host_guest_invocation_borrows_issued_input_outside_scheduling(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🎟️invocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 let input=crate::unit::original_retained_turn();assert_eq!(serde_json::to_value(input).unwrap(),law["request"]["input"]);let resources=semio_framework_actor::lane_defaults::budget_for(semio_framework_actor::Lane::Interactive);
 let policy:ShardIdentityPolicy=serde_json::from_str(include_str!("../⚙️configuration/🔣️.json")).unwrap();let mut identity=OriginalShardIdentity::issue(policy,Box::new(|_|true),Box::new(|_|Ok(()))).unwrap();let address=std::ptr::from_ref(identity.recipient.as_ref().get_ref());let native_bytes=identity.owned_bytes();
 let runtime=GuestRuntimes::Recording(Arc::new(semio_framework_plugin_host_guest_runtime::RecordingRuntime::new().await));let mut instance=GuestInstance{actor:semio_framework_actor::ActorId(71),state:semio_framework_plugin_host_guest_runtime::GuestInstanceState::Mock(semio_framework_plugin_host_guest_runtime::MockInstanceState::default())};
 let budget=semio_framework_plugin_host_shard::turn_budget_from_grant(&resources,input,input.grant,input.work.fuel,input.work.absolute_deadline_us).await;assert_eq!(budget.retained,input);
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(identity.execute_turn(&runtime,&mut instance,&[],budget)));let result=result.unwrap();assert_eq!(result.retained_receipt.input,input);assert_eq!(serde_json::to_value(result.retained_receipt.spent).unwrap(),law["spent"]);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(identity.owned_bytes(),native_bytes);assert_eq!(std::ptr::from_ref(identity.recipient.as_ref().get_ref()),address);
}
